import{_ as r,o as s,c as t,ak as a}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy shared board service","description":"The existing Cloudflare Worker now powers the team board. Trello synchronization is retired. The old durable namespace is preserved without active jobs; its prior implementati","frontmatter":{"title":"Chainy shared board service","description":"The existing Cloudflare Worker now powers the team board. Trello synchronization is retired. The old durable namespace is preserved without active jobs; its prior implementati","source":"tools/kanban-sync/README.md","category":"Guides & tooling","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/tools/kanban-sync/readme.md","filePath":"content/tools/kanban-sync/readme.md"}'),o={name:"content/tools/kanban-sync/readme.md"};function i(n,e,d,c,p,h){return s(),t("div",null,[...e[0]||(e[0]=[a('<div><h1 id="chainy-shared-board-service">Chainy shared board service<a class="header-anchor" href="#chainy-shared-board-service" aria-label="Link to this section">​</a></h1><p>The existing Cloudflare Worker now powers the <a href="https://owenlim225.github.io/Chainy-Docs/board/">team board</a>. Trello synchronization is retired. The old durable namespace is preserved without active jobs; its prior implementation remains in Git history.</p><h2 id="runtime">Runtime<a class="header-anchor" href="#runtime" aria-label="Link to this section">​</a></h2><p>GitHub Pages serves the static interface from tools/team-board/public. One SQLite Durable Object stores the five accounts, hashed sessions, tasks, immutable audit entries and a GitHub retry queue. Task writes, history and queued copies commit together. Version checks reject stale edits; operation keys make retries safe. Deletion is recoverable. All five accounts have equal task permissions.</p><p>Passwords use salted scrypt (N=32768, r=8, p=3). Only hashes are stored. Random sessions expire after 12 hours; the browser keeps its token in sessionStorage. A successful new sign-in replaces that account&#39;s previous session. Login attempts are limited by account and IP. The first sign-in requires a password change. HTTPS, exact-origin CORS, parameterized SQL, bounded requests and literal-text rendering protect the main boundaries.</p><p>Cloudflare&#39;s <a href="https://developers.cloudflare.com/workers/runtime-apis/nodejs/crypto/">Node crypto support</a> supplies scrypt. The board uses the existing account and existing GitHub secret; no new paid service is required. Monitor actual account limits as usage grows.</p><h2 id="operations">Operations<a class="header-anchor" href="#operations" aria-label="Link to this section">​</a></h2><p>Run npm run check and npm test here. The test uses the real local Workers runtime with mocked GitHub requests. Build a dry run with npm run deploy:check; deploy with npx wrangler deploy. Run node tools/team-board/check-browser.mjs from the repository root after the service test build for desktop and phone interaction checks.</p><p>The production secrets are ADMIN_TOKEN and GITHUB_TOKEN. Never put them in source or browser files. The provisioner tools/team-board/Manage-Board.ps1 reads the existing encrypted worker credentials from the current Windows user&#39;s local application-data directory. Actions: Status, Bootstrap, Backup, ResetPassword (with Username). Bootstrap refuses a board that already has users or tasks. Reset revokes the member&#39;s old sessions. Temporary passwords and the private HTML handoff are written outside this repository.</p><p>The service&#39;s admin export and a member&#39;s Export backup contain task data and audit history, not credentials. Keep dated exports before maintenance. Cloudflare storage recovery remains available under the account&#39;s retention window; verify that window in the dashboard before relying on it. Restoring from exported JSON needs a reviewed recovery operation; no public import/reset endpoint exists.</p><p>GitHub copies are one-way from the board. A durable outbox retries errors with capped backoff. Existing issue IDs are reused. Previous Project item IDs remain as historical mappings. New tasks recover any issue created before a response was lost by searching for their internal marker. The queue is visible to members and in admin Status. Do not edit managed issue bodies directly. Comments are not mirrored.</p><h2 id="boundaries">Boundaries<a class="header-anchor" href="#boundaries" aria-label="Link to this section">​</a></h2><p>The interface checks for team updates every 10 seconds, not on every keystroke. No offline editing queue, participant storage or cloud gameplay is provided. School milestones are fixed; task dates are proposals. The API currently caps the board at 1,000 tasks.</p></div>',1)])])}const m=r(o,[["render",i]]);export{u as __pageData,m as default};
